import tomllib,sys,pathlib;W=pathlib.Path(sys.argv[1]);hits=[];bad=[]
for m in sorted(list(W.glob('crates/*/Cargo.toml'))+list(W.glob('apps/*/Cargo.toml'))):
  d=tomllib.loads(m.read_text());tables=[('',d)]+[('target.'+k,v) for k,v in d.get('target',{}).items()]
  for prefix,t in tables:
    for sec in ('dependencies','build-dependencies','dev-dependencies'):
      for name,dep in t.get(sec,{}).items():
        if isinstance(dep,dict) and 'test-fixture' in dep.get('features',[]):
          (hits if sec=='dev-dependencies' and m.parent.name=='components' and prefix=='' else bad).append((str(m.relative_to(W)),prefix+sec,name))
print('dev',hits,'other',bad);sys.exit(0 if hits and not bad else 1)
